<?php
session_start();require_once 'function_admin.php';require_once dirname(__DIR__).'/kce/lib.php';
if(!isset($_SESSION['loggedin'])){header('Location: login.php');exit;}$loginemail_admin=(string)($_SESSION['loginemail_admin']??'Admin');$error='';$success='';
function kce_article_source(array $a):string{$plain=trim(preg_replace('/\s+/u',' ',html_entity_decode(strip_tags((string)$a['html_content']),ENT_QUOTES|ENT_HTML5,'UTF-8')));return trim((string)$a['title'])."\n".trim((string)$a['topic'])."\n".trim((string)$a['tag'])."\n".mb_substr($plain,0,12000);}
try{$db=kce_db();
 if($_SERVER['REQUEST_METHOD']==='POST'){
  if(!admin_csrf_valid())throw new RuntimeException('Token keamanan tidak valid.');$action=(string)($_POST['action']??'');
  if($action==='index'){$ids=array_slice(array_values(array_unique(array_filter(array_map('intval',(array)($_POST['article_ids']??[])),$fn=fn($v)=>$v>0))),0,20);if(!$ids)throw new RuntimeException('Pilih minimal satu artikel.');$indexed=0;$model=(string)(kce_env()['NVIDIA_EMBEDDING_MODEL']??'nvidia/nemotron-3-embed-1b');
   $get=$db->prepare('SELECT id,title,html_content,tag,topic FROM articles WHERE id=? AND ispublished=1');$put=$db->prepare('INSERT INTO kce_article_embeddings(article_id,embedding,embedding_model,source_hash,is_active,indexed_at) VALUES(?,?,?,?,1,NOW()) ON DUPLICATE KEY UPDATE embedding=VALUES(embedding),embedding_model=VALUES(embedding_model),source_hash=VALUES(source_hash),is_active=1,indexed_at=NOW()');
   foreach($ids as $id){$get->bind_param('i',$id);$get->execute();$a=$get->get_result()->fetch_assoc();if(!$a)continue;$source=kce_article_source($a);$vector=kce_embedding($source,'passage');$json=json_encode($vector);$hash=hash('sha256',$source);$put->bind_param('isss',$id,$json,$model,$hash);$put->execute();$indexed++;}$get->close();$put->close();$success="$indexed artikel berhasil dibuatkan embedding 2048 dimensi.";
  }elseif($action==='toggle'){$id=(int)$_POST['article_id'];$s=$db->prepare('UPDATE kce_article_embeddings SET is_active=1-is_active WHERE article_id=?');$s->bind_param('i',$id);$s->execute();$s->close();$success='Status indeks artikel diperbarui.';
  }elseif($action==='settings'){$threshold=(float)$_POST['article_relevance_threshold'];$max=(int)$_POST['max_article_results'];if($threshold<0||$threshold>1||$max<0||$max>10)throw new RuntimeException('Pengaturan artikel di luar rentang.');$s=$db->prepare('INSERT INTO kce_settings(setting_key,setting_value) VALUES(?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)');foreach(['article_relevance_threshold'=>(string)$threshold,'max_article_results'=>(string)$max] as $k=>$v){$s->bind_param('ss',$k,$v);$s->execute();}$s->close();$success='Pengaturan artikel relevan disimpan.';}
 }
 $settings=[];foreach($db->query('SELECT setting_key,setting_value FROM kce_settings') as $r)$settings[$r['setting_key']]=$r['setting_value'];$search=trim((string)($_GET['q']??''));$like='%'.$search.'%';$page=max(1,(int)($_GET['page']??1));$limit=30;$offset=($page-1)*$limit;
 $where="a.ispublished=1".($search!==''?' AND (a.title LIKE ? OR a.tag LIKE ? OR a.topic LIKE ?)':'');$count=$db->prepare("SELECT COUNT(*) FROM articles a WHERE $where");if($search!=='')$count->bind_param('sss',$like,$like,$like);$count->execute();$total=(int)$count->get_result()->fetch_column();$count->close();
 $sql="SELECT a.id,a.title,a.tag,a.topic,a.updated_at,a.html_content,pq.username,pq.description author_description,e.embedding_model,e.source_hash,e.is_active,e.indexed_at FROM articles a LEFT JOIN publisher_quota pq ON pq.publisher_id=a.publishers_local_id LEFT JOIN kce_article_embeddings e ON e.article_id=a.id WHERE $where ORDER BY a.updated_at DESC LIMIT ?,?";$s=$db->prepare($sql);if($search!=='')$s->bind_param('sssii',$like,$like,$like,$offset,$limit);else $s->bind_param('ii',$offset,$limit);$s->execute();$articles=$s->get_result()->fetch_all(MYSQLI_ASSOC);$s->close();
}catch(Throwable $e){$error=$e->getMessage();$articles=$articles??[];$settings=$settings??[];$total=$total??0;}
?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>KCE Article Index</title><link rel="stylesheet" href="https://stackpath.bootstrapcdn.com/bootstrap/4.5.2/css/bootstrap.min.css"><?php include 'style_toogle.php';?><link rel="stylesheet" href="kce_articles.css"></head><body><div class="admin-navbar"><a class="brand" href="dashboard_admin.php">Admin Dashboard</a><a href="logout.php"><i class="fas fa-sign-out-alt mr-1"></i> Logout</a></div><?php include 'sidebar_menu.php';?><main class="admin-main" id="mainContent"><div class="d-flex justify-content-between mb-4"><div><h2>KCE Article Index</h2><p class="text-muted">Pilih artikel editorial yang dapat ditemukan melalui semantic retrieval.</p></div><a href="kce.php" class="btn btn-outline-secondary align-self-start">KCE Dashboard</a></div><?php if($error):?><div class="alert alert-danger"><?=htmlspecialchars($error)?></div><?php endif;?><?php if($success):?><div class="alert alert-success"><?=htmlspecialchars($success)?></div><?php endif;?>
<div class="card mb-4"><div class="card-body"><form method="post" class="form-row"><?=admin_csrf_field()?><input type="hidden" name="action" value="settings"><div class="col-md-4"><label>Ambang relevansi artikel (0–1)</label><input class="form-control" type="number" min="0" max="1" step=".01" name="article_relevance_threshold" value="<?=htmlspecialchars($settings['article_relevance_threshold']??'.30')?>"></div><div class="col-md-4"><label>Maksimum artikel per jawaban</label><input class="form-control" type="number" min="0" max="10" name="max_article_results" value="<?=htmlspecialchars($settings['max_article_results']??'3')?>"></div><div class="col-md-4 d-flex align-items-end"><button class="btn btn-success">Simpan pengaturan</button></div></form></div></div>
<div class="card"><div class="card-body"><div class="d-flex justify-content-between flex-wrap mb-3"><form method="get" class="form-inline"><input class="form-control mr-2" name="q" value="<?=htmlspecialchars($search??'')?>" placeholder="Cari judul, tag, topik"><button class="btn btn-outline-secondary">Cari</button></form><span class="text-muted align-self-center"><?=number_format($total)?> artikel terbit</span></div><form method="post"><?=admin_csrf_field()?><input type="hidden" name="action" value="index"><div class="table-responsive"><table class="table table-hover"><thead><tr><th><input type="checkbox" id="all"></th><th>Artikel</th><th>Indeks KCE</th><th>Model / waktu</th><th>Aksi</th></tr></thead><tbody><?php foreach($articles as $a):$indexed=!empty($a['source_hash']);$currentHash=hash('sha256',kce_article_source($a));$stale=$indexed&&!hash_equals((string)$a['source_hash'],$currentHash);?><tr><td><input type="checkbox" name="article_ids[]" value="<?=(int)$a['id']?>"></td><td><strong><?=htmlspecialchars($a['title']?:'Tanpa judul')?></strong><br><small class="text-muted"><?=htmlspecialchars(mb_substr((string)($a['topic']?:$a['tag']),0,110))?></small><?php $author=(string)($a['username']?:'Author');$slug=str_replace(' ','_',preg_replace('/[^A-Za-z0-9 ]/','',(string)$a['title']));?><div class="article-meta"><span><i class="fas fa-user-edit"></i> Penulis: <a href="/blog/<?=rawurlencode($author)?>" target="_blank" rel="noopener"><?=htmlspecialchars($author)?></a></span><a href="/blog/<?=rawurlencode($author)?>/<?=(int)$a['id']?>/<?=rawurlencode($slug)?>" target="_blank" rel="noopener"><i class="fas fa-external-link-alt"></i> Lihat artikel</a></div></td><td><?php if(!$indexed):?><span class="status-dot off"></span>Belum diindeks<?php elseif($stale):?><span class="status-dot stale"></span>Perlu diperbarui<?php elseif($a['is_active']):?><span class="status-dot on"></span>Aktif · 2048 dimensi<?php else:?><span class="status-dot off"></span>Nonaktif<?php endif;?></td><td><small><?=htmlspecialchars($a['embedding_model']??'-')?><br><?=htmlspecialchars($a['indexed_at']??'-')?></small></td><td><?php if($indexed):?><button form="toggle-<?=(int)$a['id']?>" class="btn btn-sm btn-outline-warning"><?=$a['is_active']?'Nonaktifkan':'Aktifkan'?></button><?php endif;?></td></tr><?php endforeach;?><?php if(!$articles):?><tr><td colspan="5" class="text-center text-muted">Artikel tidak ditemukan.</td></tr><?php endif;?></tbody></table></div><button class="btn btn-success">Buat / perbarui embedding pilihan</button></form><?php foreach($articles as $a):if(empty($a['source_hash']))continue;?><form id="toggle-<?=(int)$a['id']?>" method="post" class="d-none"><?=admin_csrf_field()?><input name="action" value="toggle"><input name="article_id" value="<?=(int)$a['id']?>"></form><?php endforeach;?><nav class="mt-3"><?php $pages=(int)ceil($total/$limit);for($p=max(1,$page-2);$p<=min($pages,$page+2);$p++):?><a class="btn btn-sm <?=$p===$page?'btn-success':'btn-light'?>" href="?q=<?=urlencode($search)?>&page=<?=$p?>"><?=$p?></a><?php endfor;?></nav></div></div></main><script>document.querySelector('#all')?.addEventListener('change',e=>document.querySelectorAll('input[name="article_ids[]"]').forEach(x=>x.checked=e.target.checked))</script><?php include 'js_toogle.php';?></body></html>
